from collections import deque, Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])

    # Find background color (most common)
    colors = []
    for row in grid:
        colors.extend(row)
    bg_color = Counter(colors).most_common(1)[0][0]

    # BFS from border cells to find all background cells touching border
    visited = [[False]*w for _ in range(h)]
    queue = deque()

    for row in range(h):
        for col in range(w):
            if grid[row][col] == bg_color:
                if row == 0 or row == h-1 or col == 0 or col == w-1:
                    visited[row][col] = True
                    queue.append((row, col))

    while queue:
        row, col = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == bg_color and not visited[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Fill all unreachable background cells with 2
    result = [row[:] for row in grid]
    for row in range(h):
        for col in range(w):
            if grid[row][col] == bg_color and not visited[row][col]:
                result[row][col] = 2

    return result

